#include <cstdio>
#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

long long power(long long base, int exp, int mod) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    int n, k, MO;
    cin >> n >> k >> MO;
    if (n % 2 == 1) {
        cout << power(k, n, MO) << endl;
        return 0;
    }
    vector<long long> factorial(n + 1, 1), inv_factorial(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        factorial[i] = (factorial[i - 1] * i) % MO;
    }
    inv_factorial[n] = power(factorial[n], MO - 2, MO);
    for (int i = n - 1; i >= 0; --i) {
        inv_factorial[i] = (inv_factorial[i + 1] * (i + 1)) % MO;
    }
    int t = n;
    vector<int> a, s_list;
    for (int i = 0; i <= 20; ++i) {
        if (t & 1) a.push_back(1 << i);
        t >>= 1;
    }
    int S_size = 1 << a.size();
    vector<int> S(S_size, 0);
    for (int i = 0; i < S_size; ++i) {
        for (int j = 0; j < (int)a.size(); ++j) {
            if ((i >> j) & 1) S[i] += a[j];
        }
    }
    vector<int> p(S_size, -1);
    for (int i = 0; i < S_size; ++i) {
        int t_idx = -1;
        for (int j = 0; j <= 20; ++j) {
            if ((i >> j) & 1) t_idx = j;
        }
        p[i] = (1 << (t_idx + 1)) + i;
    }
    vector<vector<long long>> f(k + 1, vector<long long>(S_size, 0));
    f[0][0] = 1;
    for (int i = 0; i < k; ++i) {
        for (int j = 0; j < S_size; ++j) {
            if (f[i][j]) {
                for (int k_idx = p[j]; k_idx < S_size; k_idx = (k_idx + 1) | j) {
                    int diff = S[k_idx ^ j];
                    long long inv_val = inv_factorial[diff];
                    f[i + 1][k_idx] = (f[i + 1][k_idx] + f[i][j] * inv_val) % MO;
                }
            }
        }
    }
    long long ans = 0;
    for (int i = 0; i <= k; ++i) {
        long long comb = (factorial[k] * inv_factorial[i] % MO) * inv_factorial[k - i] % MO;
        ans = (ans + f[i][S_size - 1] * comb) % MO;
    }
    ans = (ans * factorial[n]) % MO;
    long long total = power(k, n, MO);
    long long result = (total - ans + MO) % MO;
    cout << result << endl;
    return 0;
}
